// Generates the production dependency licence list for THIRD_PARTY_NOTICES.md and apps/web/src/lib/dependency-licenses.ts
// (M10 T0b). Run: node tools/generate-notices.mjs. It reads `pnpm licenses list --prod --json` (nothing is installed or
// downloaded) and the verbatim copyright lines of the font packages, and rewrites the two generated files. The hand-written
// TradingView / Apache text of THIRD_PARTY_NOTICES.md (above the marker) is kept.
import { execSync } from 'node:child_process';
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const root = new URL('..', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1');
const json = JSON.parse(
  execSync('pnpm licenses list --prod --json', {
    cwd: root,
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  }),
);
const PERMISSIVE = new Set([
  'MIT',
  'ISC',
  'BSD-2-Clause',
  'BSD-3-Clause',
  'Apache-2.0',
  '0BSD',
  'BlueOak-1.0.0',
  'Python-2.0',
]);
const ACCEPTED_BY_FOUNDER = new Set(['OFL-1.1', 'CC-BY-4.0', 'Apache-2.0 AND LGPL-3.0-or-later']); // D-116

const rows = [];
for (const [license, pkgs] of Object.entries(json)) {
  for (const p of pkgs)
    for (const v of p.versions) rows.push({ name: p.name, version: v, license });
}
rows.sort((a, b) =>
  a.name === b.name ? a.version.localeCompare(b.version) : a.name.localeCompare(b.name),
);
const unknown = [...new Set(rows.map((r) => r.license))].filter(
  (l) => !PERMISSIVE.has(l) && !ACCEPTED_BY_FOUNDER.has(l),
);
if (unknown.length > 0) {
  console.error('NOT PERMISSIVE and not accepted: ' + unknown.join(', '));
  process.exit(2);
}

const pnpmDir = join(root, 'node_modules', '.pnpm');
const find = (prefix, sub) => {
  const d = readdirSync(pnpmDir).find((x) => x.startsWith(prefix));
  return d === undefined ? null : join(pnpmDir, d, 'node_modules', sub);
};
const firstLine = (file) => readFileSync(file, 'utf8').split('\n')[0].trim();
const inter = firstLine(find('@fontsource-variable+inter@', '@fontsource-variable/inter/LICENSE'));
const mono = firstLine(
  find('@fontsource-variable+jetbrains-mono@', '@fontsource-variable/jetbrains-mono/LICENSE'),
);
const OFL_URL =
  'https://openfontlicense.org/ (SIL Open Font License, Version 1.1, 26 February 2007)';
const CCBY =
  'Browser support data in caniuse-lite is from caniuse.com and is licensed under the Creative Commons Attribution 4.0 International licence (CC BY 4.0, https://creativecommons.org/licenses/by/4.0/). It is used at build time to choose browser targets and is not shown to users.';
const SHARP =
  'Next.js lists an optional image-optimisation binary (@img/sharp-*, with libvips, Apache-2.0 AND LGPL-3.0-or-later). VANTAGE never uses next/image and the binary is not part of the container images (see docs/DOCKER.md); it is an optional development-time binary only.';

const marker = '<!-- GENERATED BELOW (tools/generate-notices.mjs) -->';
const mdFile = join(root, 'THIRD_PARTY_NOTICES.md');
let md = readFileSync(mdFile, 'utf8');
const at = md.indexOf(marker);
if (at >= 0) md = md.slice(0, at).trimEnd() + '\n';
md += `
${marker}

## Fonts (SIL Open Font License 1.1)

- ${inter}
- ${mono}

These fonts are licensed under the SIL Open Font License, Version 1.1 (${OFL_URL}). They are self-hosted through the @fontsource-variable packages.

## Browser data (CC BY 4.0)

${CCBY}

## Optional image binary

${SHARP}

## Production dependencies (${rows.length} package versions; name, version, SPDX licence)

| Package | Version | Licence |
| --- | --- | --- |
${rows.map((r) => `| ${r.name} | ${r.version} | ${r.license} |`).join('\n')}
`;
writeFileSync(mdFile, md);

const ts = `// GENERATED by tools/generate-notices.mjs (M10 T0b): do not edit by hand.
export interface DependencyLicense {
  readonly name: string;
  readonly version: string;
  readonly license: string;
}
export const FONT_NOTICES: readonly string[] = ${JSON.stringify([inter, mono])};
export const OFL_REFERENCE = ${JSON.stringify(OFL_URL)};
export const CCBY_NOTICE = ${JSON.stringify(CCBY)};
export const SHARP_NOTICE = ${JSON.stringify(SHARP)};
export const DEPENDENCY_LICENSES: readonly DependencyLicense[] = ${JSON.stringify(rows)};
`;
writeFileSync(join(root, 'apps', 'web', 'src', 'lib', 'dependency-licenses.ts'), ts);
console.log(
  `ok: ${rows.length} package versions; licences: ${[...new Set(rows.map((r) => r.license))].join(', ')}`,
);
